CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY,checksum TEXT NOT NULL,applied_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','user')),disabled INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE collections(id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE REFERENCES users(id),schema_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf_hash TEXT NOT NULL,created_at INTEGER NOT NULL,last_used INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE one_time_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,purpose TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE field_definitions(id TEXT PRIMARY KEY,collection_id TEXT NOT NULL REFERENCES collections(id),type TEXT NOT NULL,data TEXT NOT NULL,UNIQUE(collection_id,id));
CREATE TABLE field_options(id TEXT NOT NULL,collection_id TEXT NOT NULL,field_id TEXT NOT NULL,PRIMARY KEY(collection_id,field_id,id),FOREIGN KEY(collection_id,field_id) REFERENCES field_definitions(collection_id,id) ON DELETE CASCADE);
CREATE TABLE tags(id TEXT PRIMARY KEY,collection_id TEXT NOT NULL,field_id TEXT NOT NULL,name TEXT NOT NULL,normalized_name TEXT NOT NULL,palette_id TEXT NOT NULL CHECK(palette_id IN ('lime','green','teal','cyan','blue','indigo','violet','pink','red','orange','amber','slate')),version INTEGER NOT NULL DEFAULT 1,UNIQUE(collection_id,field_id,normalized_name),UNIQUE(collection_id,field_id,id),FOREIGN KEY(collection_id,field_id) REFERENCES field_definitions(collection_id,id) ON DELETE CASCADE);
CREATE TABLE liquids(id TEXT PRIMARY KEY,collection_id TEXT NOT NULL REFERENCES collections(id),name TEXT NOT NULL,normalized_name TEXT NOT NULL,favorite INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,UNIQUE(collection_id,id));
CREATE TABLE media(id TEXT PRIMARY KEY,collection_id TEXT NOT NULL REFERENCES collections(id),data TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(collection_id,id));
CREATE TABLE field_values(collection_id TEXT NOT NULL,liquid_id TEXT NOT NULL,field_id TEXT NOT NULL,type TEXT NOT NULL,value_text TEXT,value_search TEXT,value_number INTEGER,value_bool INTEGER CHECK(value_bool IN(0,1)),value_media TEXT,value_option TEXT,PRIMARY KEY(collection_id,liquid_id,field_id),CHECK((type IN ('text','longtext','color','date') AND value_text IS NOT NULL) OR (type IN ('number','rating') AND value_number IS NOT NULL) OR (type='boolean' AND value_bool IS NOT NULL) OR (type='image' AND value_media IS NOT NULL) OR (type='select' AND value_option IS NOT NULL)),CHECK((value_text IS NOT NULL)+(value_number IS NOT NULL)+(value_bool IS NOT NULL)+(value_media IS NOT NULL)+(value_option IS NOT NULL)=1),FOREIGN KEY(collection_id,liquid_id) REFERENCES liquids(collection_id,id) ON DELETE CASCADE,FOREIGN KEY(collection_id,field_id) REFERENCES field_definitions(collection_id,id) ON DELETE CASCADE,FOREIGN KEY(collection_id,value_media) REFERENCES media(collection_id,id),FOREIGN KEY(collection_id,field_id,value_option) REFERENCES field_options(collection_id,field_id,id));
CREATE TRIGGER field_value_type_insert BEFORE INSERT ON field_values WHEN NEW.type != (SELECT type FROM field_definitions WHERE id=NEW.field_id AND collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'field type mismatch'); END;
CREATE TABLE liquid_tags(collection_id TEXT NOT NULL,liquid_id TEXT NOT NULL,field_id TEXT NOT NULL,tag_id TEXT NOT NULL,PRIMARY KEY(collection_id,liquid_id,field_id,tag_id),FOREIGN KEY(collection_id,liquid_id) REFERENCES liquids(collection_id,id) ON DELETE CASCADE,FOREIGN KEY(collection_id,field_id,tag_id) REFERENCES tags(collection_id,field_id,id) ON DELETE CASCADE);
CREATE TABLE user_preferences(user_id TEXT PRIMARY KEY REFERENCES users(id),version INTEGER NOT NULL DEFAULT 1,data TEXT NOT NULL);
CREATE TABLE dashboards(user_id TEXT PRIMARY KEY REFERENCES users(id),version INTEGER NOT NULL DEFAULT 1,data TEXT NOT NULL);
CREATE TABLE saved_views(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),version INTEGER NOT NULL DEFAULT 1,data TEXT NOT NULL);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,user_id TEXT,action TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX liquids_page ON liquids(collection_id,deleted_at,created_at,id);
CREATE INDEX liquids_favorite ON liquids(collection_id,favorite);
CREATE INDEX values_number ON field_values(collection_id,field_id,value_number,liquid_id);
CREATE INDEX values_text ON field_values(collection_id,field_id,value_text,liquid_id);
CREATE INDEX tags_filter ON liquid_tags(collection_id,field_id,tag_id,liquid_id);
PRAGMA user_version=1;

CREATE TRIGGER field_value_type_update BEFORE UPDATE ON field_values WHEN NEW.type != (SELECT type FROM field_definitions WHERE id=NEW.field_id AND collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'field type mismatch'); END;
CREATE TRIGGER tag_field_type BEFORE INSERT ON tags WHEN (SELECT type FROM field_definitions WHERE id=NEW.field_id AND collection_id=NEW.collection_id)!='tags' BEGIN SELECT RAISE(ABORT,'tag field required'); END;
